#!/usr/bin/env python3
"""Q241: data/derived/Q241_pose_asymmetry.json -> data/derived/Q241_pose_asymmetry.md"""
import json, sys
from pathlib import Path
import numpy as np
REPO = Path(__file__).resolve().parents[3]
J = REPO / "data/derived/Q241_pose_asymmetry.json"
OUT = REPO / "data/derived/Q241_pose_asymmetry.md"
ORDER = ["base_m", "base_f", "comb_m", "comb_f", "own_m", "own_f"]
BASIC = ("base_m", "base_f")
NAMES = {"base_m": "Base · Male (Z-Anatomy, unadapted)", "base_f": "Base · Female (Z-Anatomy generic body, female variant)", "comb_m": "Combined · Male", "comb_f": "Combined · Female",
         "own_m": "Imaging-based · Male", "own_f": "Imaging-based · Female"}
SHOW = [("shoulder", "flex"), ("shoulder", "abd"), ("shoulder", "rot"), ("elbow", "flex"), ("forearm", "sup"), ("wrist", "flex"), ("wrist", "dev"), ("hip", "flex"), ("hip", "abd"), ("hip", "rot"),
        ("knee", "flex"), ("ankle", "dp"), ("subtalar", "inv")]


def f(x, n=1):
    return "-" if x is None else ("%.*f" % (n, x))


def main():
    d = json.load(open(J))
    th = d["thresholds"]
    L = []
    w = L.append
    w("# Q241 - left / right POSE difference of the six models, separated from tissue anatomy\n")
    w("Generated by `scripts/anatomy/q241/run_asym.py` (+ `asym.py`, `rig.py`, `skeleton.py`, `skin.py`); machine-readable: `data/derived/Q241_pose_asymmetry.json`. Reads the CURRENT pages (build/q238 = hub v34), never edits them. "
      "Frame: mm, +X = the subject's right. Builds on Q237 (`Q237_pairing.json`: pairing, midsagittal planes, tissue metrics).\n")
    w("## 1. Method\n")
    w("* **Joint angles of the skeleton as built.** Landmarks are computed from each page's OWN bones (femoral / humeral head spheres, epicondylar axes, malleolar axis, sole plane from heel + metatarsal heads, "
      "ASIS / PSIS of the pelvis, radial vs ulnar styloid, finger / toe joint centres ...). The LEFT limb is reflected about the model's midsagittal plane first, so every limb is measured as a RIGHT limb and equal "
      "numbers mean the same anatomical posture. Shoulder / hip: flexion about the mediolateral axis, then abduction, then rotation (intrinsic order, relative to the trunk / pelvis frame). Elbow, knee: hinge angle. "
      "Forearm: AAOS convention (0 = neutral, + = supination). Wrist, fingers, ankle (talocrural) and subtalar angle as defined in `docs/pose_rom_table.md` / `rig.py`. Palmar direction from the forearm flexor vs extensor muscles "
      "of the same model. Difference = right - left.\n"
      "* **Bone registration.** The mirrored LEFT bones of every segment are rigidly registered (trimmed ICP, 5 initialisations) onto the RIGHT bones: the world rotation / translation that would give the left segment the "
      "mirrored right pose (midline bones are registered onto themselves = rotation of the segment about its own symmetry plane).\n"
      "* **Spine / pelvis / head.** The bilateral-symmetry plane of every vertebra, of the pelvis (hip bones + sacrum), the skull and the thorax is fitted (mirror chamfer, Nelder-Mead) and compared with the model plane: "
      "axial rotation (+ = turned to the subject's left) and lateral tilt (+ = right side up). Pelvic tilt / obliquity / rotation = pelvis frame (hip centres, ASIS / PSIS) against the trunk frame.\n"
      "* **Tissue before / after pose normalisation.** For every paired structure of the Q237 table the mirrored left tissue is moved by the per-bone rigid registration of its segments (linear blend skinning with the weights of the pose rig, "
      "`skin.py`) and IoU / centroid offset / mean surface distance are recomputed against the right structure with the Q237 voxel code. `IoU mirror` = Q237 (mirroring only), `IoU pose` = after the bone-driven alignment, "
      "`IoU ICP` = Q237's per-structure ICP (an upper bound that uses the tissue itself, not the bones). Volume ratios are pose-invariant.\n")
    w("## 2. Thresholds (ASSUMPTIONS, stated, not from a single standard)\n")
    w("Resting left-right differences of healthy adults standing in a relaxed posture are a few degrees (pelvic obliquity and trunk lateral deviation below about 2-3 degrees, hip / knee / ankle angles within about 5 degrees; "
      "gait-symmetry literature, e.g. Sadeghi et al. 2000, Herzog et al. 1989; leg-length / pelvic obliquity: Knutson 2005). Used here: " +
      ", ".join("%s %.0f deg" % (k, v) for k, v in th["group_deg"].items()) + "; rotations about a long axis (shoulder / hip rotation, forearm, subtalar) tolerance x%.1f because landmarks define them less well; "
      "finger / toe groups are judged on the mean over the joints (landmark noise of tiny bones is about 4 deg on the Z-Anatomy bones). "
      "Tissue: IoU >= %.1f and volume ratio R/L in %.2f-%.2f (the Q237 flags). **Verdict 'reasonable'** = no tolerance exceeded; otherwise 'needs fix' for the BASIC models (they must be symmetric fit targets) and "
      "'posture-asymmetric specimen' for the reconstructed pages (their asymmetry is measured; never overwritten).\n" % (1.6, th["iou_min"], th["ratio"][0], th["ratio"][1]))
    for key in ORDER:
        p = d["pages"].get(key)
        if not p:
            continue
        ex = p["exceed"]
        w("## 3.%d %s\n" % (ORDER.index(key) + 1, NAMES[key]))
        if key in BASIC:
            verdict = "**reasonable**" if not ex else "**needs fix**"
            w("Verdict: %s. %s\n" % (verdict, "Both sides are mirror copies in Z-Anatomy: the skeleton is symmetric to %.2f mm median / %.2f mm p95 (nearest-surface distance of the mirrored left bones to the right bones, no alignment), "
              "all %d joint angles agree within <= %.1f deg (largest: %s). The A-pose is identical on both sides BY DESIGN (shoulder abduction about 10 deg, elbows about 15 deg flexed, forearms near full supination, "
              "fingers relaxed), so there is nothing to correct: no re-posing was applied and no geometry changed (ship-diff 0)." %
              (p["bone_pairs_median_msd_mm"], p["bone_pairs_p95_msd_mm"], len(p["angles"]), max(abs(r["diff"]) for r in p["angles"] if r["group"] not in ("fingers", "toes")), max(p["angles"], key=lambda r: abs(r["diff"]) if r["group"] not in ("fingers", "toes") else 0)["joint"]) if not ex else ""))
        else:
            w("Verdict: **posture-asymmetric specimen** (measured; not corrected). Beyond tolerance: %s.\n" % ("; ".join("%s %s %+.1f (tol %.1f)" % (e["joint"], e["dof"], e["diff"], e["tolerance"]) for e in ex) or "none"))
        w("### Pose table (degrees; joint angles as built, right / left / right - left)\n")
        w("| joint | DOF | right | left | R - L |\n|---|---|---|---|---|")
        rows = {(r["joint"], r["dof"]): r for r in p["angles"]}
        for jn, dn in SHOW:
            r = rows.get((jn, dn))
            if r:
                w("| %s | %s | %s | %s | %s |" % (jn, r["label"], f(r["right"]), f(r["left"]), f(r["diff"])))
        for g, nm in (("fingers", "fingers + thumb (MCP / PIP / DIP / CMC / IP)"), ("toes", "toes (MTP / PIP / DIP / IP)")):
            v = [abs(r["diff"]) for r in p["angles"] if r["group"] == g]
            if v:
                w("| %s | mean / max abs R-L over %d joints%s | | | %.1f / %.1f |" % (nm, len(v), "" if key in BASIC else " (indicative only: the fitted Z hand / foot bones are warped, errors of 20 deg are possible)", np.mean(v), np.max(v)))
            else:
                w("| %s | not available on this page: the bone meshes of all phalanges are merged; the hand / foot moves as one segment | | | |" % nm)
        pv = p["pelvis_vs_trunk"]
        tr = {t["item"]: t for t in p["trunk"]}
        w("\nTrunk, pelvis, head (symmetry planes against the midsagittal plane; rotation + = turned to the subject's left, tilt + = right side up):\n")
        w("| item | rotation | tilt / obliquity |\n|---|---|---|")
        w("| pelvis frame vs trunk: tilt / obliquity / rotation | %s | %s / %s / %s |" % ("-", f(pv["tilt_deg"]), f(pv["obliquity_deg"]), f(pv["rotation_deg"])))
        for nm in ("pelvis (hip bones + sacrum)", "thorax (ribs + sternum)", "skull"):
            if nm in tr:
                w("| %s | %s | %s |" % (nm, f(tr[nm]["rotation_deg"]), f(tr[nm]["tilt_deg"])))
        for reg in ("cervical", "thoracic", "lumbar"):
            vv = [t for t in p["trunk"] if t.get("region") == reg and t["item"].startswith("vertebra")]
            if vv:
                w("| %s vertebrae (%d), mean; max abs centroid offset from the plane %.1f mm | %s | %s |" % (reg, len(vv), max(abs(t["centroid_offset_mm"]) for t in vv), f(np.mean([t["rotation_deg"] for t in vv])), f(np.mean([t["tilt_deg"] for t in vv]))))
        sr = sorted([s for s in p["segment_registration"] if s.get("n", 0) >= 1000], key=lambda s: -s["rot_deg"])
        w("\nBone registration (mirrored left onto right, rigid, world): largest segment rotations: " + ", ".join("%s %.1f deg / %.0f mm" % (s["seg"], s["rot_deg"], s["trans_mm"]) for s in sr[:8]) +
          "; median residual of the %d larger segments %.2f mm (tiny finger / toe bones are not listed: their registration is not unique).\n" % (len(sr), np.median([s["residual_mm"] for s in sr])))
        t = p["tissue"]
        w("### Tissue asymmetry before / after pose normalisation (paired structures of Q237)\n")
        w("| set | n | centroid offset mm (mirror -> pose-normalised) | mean surface dist mm | IoU mirror | IoU pose | IoU per-structure ICP | IoU >= 0.6 (mirror / pose / ICP) of n |\n|---|---|---|---|---|---|---|---|")
        for nm in ["all", "muscle"] + sorted(k for k in t if k.startswith("sys_") and k not in ("sys_muscle",) and t[k]["n"] >= 8):
            b = t[nm]
            w("| %s | %d | %s -> %s | %s -> %s | %s | %s | %s | %d / %d / %d of %d |" % (nm.replace("sys_", ""), b["n"], f(b["centroid_mm_before"]), f(b["centroid_mm_after"]), f(b["msd_mm_before"]), f(b["msd_mm_after"]),
              f(b["iou_mirror_median"], 2), f(b["iou_pose_median"], 2), f(b["iou_icp_median"], 2), b["iou_ge_06_before"], b["iou_ge_06_after"], b["iou_ge_06_icp"], b["n_iou_volume"]))
        c = t["classification"]
        w("\nClassification of the %d paired structures: symmetric already (IoU mirror >= 0.6, size ratio ok) %d; **explained by pose** (IoU mirror < 0.6, >= 0.6 after bone-driven alignment) %d; "
          "**anatomical (size)** (volume / area ratio R/L outside 0.8-1.25, pose-invariant) %d; residual shape / position difference not explained by rigid bone pose %d.\n" %
          (t["all"]["n"], c["symmetric_already"], c["explained_by_pose"], c["anatomical_size"], c["residual_shape_or_position"]))
        lists = p["tissue_lists"]
        for kk, title, keyf in (("explained_by_pose", "Largest pose effects (IoU before -> after)", lambda r: -((r["iou_pose"] or 0) - (r["iou_before"] or 0))),
                                ("anatomical_size", "Anatomical size differences (ratio R/L)", lambda r: -abs(np.log(max(r["ratio"] or 1, 1e-3)))),
                                ("residual_shape_or_position", "Unexplained residual (lowest IoU after pose normalisation)", lambda r: (r["iou_pose"] or 0))):
            ls = sorted([r for r in lists[kk] if r["sys"] in ("muscle", "bone", "vessel", "nerve", "viscera", "cartilage", "joint")], key=keyf)[:6]
            if ls:
                w("* %s: " % title + "; ".join("%s %s (ratio %s, IoU %s -> %s, centroid %s -> %s mm)" % (r["sys"], r["canon"], f(r["ratio"], 2), f(r["iou_before"], 2), f(r["iou_pose"], 2), f(r["centroid_before_mm"]), f(r["centroid_after_mm"])) for r in ls))
        w("")
    OUT.write_text("\n".join(L) + "\n", encoding="utf-8")
    print("wrote", OUT, len(L), "lines")


if __name__ == "__main__":
    main()
